#!/bin/bash
set -eo pipefail
sequence=5
root=/data1/home/sunyiq/kalmannet_hamid_weights_20260923_v1
state=$(sacct -X -j 227477 -n -P --format=State | tr -d '[:space:]|')
printf 'PREVIOUS_JOB_STATE=%s\n' "$state"
test "$state" = "FAILED"
printf '%s' '' | base64 -d | /data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B -
test -f "$root/deployment_receipt_v3.json"
bash -n "$root/probe_package_v3/probe.slurm"
mkdir "$root/probe_submission_claim_002"
set +e
submission_output=$(sbatch "$root/probe_package_v3/probe.slurm" 2>&1)
submission_exit=$?
set -e
printf '%s
' "$submission_output" | tee "$root/probe_submission_claim_002/sbatch_output.txt"
printf '%s
' "$submission_exit" > "$root/probe_submission_claim_002/sbatch_exit.txt"
job_id=$(printf '%s
' "$submission_output" | sed -n 's/^Submitted batch job \([0-9][0-9]*\)$/\1/p')
if [ "$submission_exit" -ne 0 ] || ! [[ "$job_id" =~ ^[0-9]+$ ]]; then
  printf '%s
' 'SUBMISSION_NOT_CONFIRMED_DO_NOT_RESUBMIT'
  exit 41
fi
printf '%s
' "$job_id" > "$root/probe_submission_claim_002/job_id.txt"
printf 'PROBE_SUBMITTED_JOB_ID=%s
' "$job_id"
squeue -h -j "$job_id" -o '%i|%j|%T|%R' || true
printf '%s
' 'ISOLATED_PROBE_SUBMISSION_COMPLETE'
